-- ============================================================================
-- V3 — Reference data (Phase 2A)
--
-- Normalized geography and language vocabularies. This migration is PURELY
-- ADDITIVE: nothing in the existing schema references these tables yet. The
-- links from `users` and `lawyers` arrive in a later phase, deliberately, so
-- this one can be deployed and rolled back on its own.
--
-- Design notes:
--
--   * `name_normalized` is the canonical lookup key: diacritics stripped,
--     lowercased, whitespace collapsed. It is what makes UNIQUE meaningful -
--     without it "Mumbai" and "mumbai " are two distinct rows. Generated by
--     TextNormalizer in the application layer; the values seeded below were
--     produced by the identical rule.
--
--   * `city_aliases` carries historical and colloquial names (Bombay, Calcutta,
--     Bangalore, Gurgaon...). India renamed many cities and both forms remain
--     in daily use, so without this a client typing "Bangalore" would find
--     nothing. It doubles as the mapping table for the later backfill of the
--     existing free-text `lawyers.city` column.
--
--   * Rows are deactivated (`active = false`), never deleted. Foreign keys are
--     ON DELETE RESTRICT so a city with lawyers attached cannot be removed.
--
--   * Only India is seeded. The `countries` table exists so the SHAPE supports
--     expansion; seeding 250 unusable countries would add dropdown entries that
--     lead nowhere. Adding one later is a single INSERT.
--
-- Type mapping follows V1: UUID -> uuid, String(len=N) -> varchar(N),
-- LocalDateTime -> timestamp(6), enum(STRING) -> varchar(255), boolean.
-- ============================================================================

-- Trigram matching powers city typeahead ("mumbay" -> "Mumbai"), which plain
-- equality and full-text stemming both fail at for short proper nouns.
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- ---------------------------------------------------------------- countries
CREATE TABLE countries (
    id          uuid          NOT NULL,
    created_at  timestamp(6)  NOT NULL,
    updated_at  timestamp(6)  NOT NULL,
    iso2        varchar(2)    NOT NULL,
    iso3        varchar(3)    NOT NULL,
    name        varchar(100)  NOT NULL,
    phone_code  varchar(8)    NOT NULL,
    active      boolean       NOT NULL DEFAULT true,
    CONSTRAINT pk_countries PRIMARY KEY (id),
    CONSTRAINT uq_countries_iso2 UNIQUE (iso2),
    CONSTRAINT uq_countries_iso3 UNIQUE (iso3)
);

-- ------------------------------------------------------------------- states
CREATE TABLE states (
    id               uuid          NOT NULL,
    created_at       timestamp(6)  NOT NULL,
    updated_at       timestamp(6)  NOT NULL,
    country_id       uuid          NOT NULL,
    code             varchar(10)   NOT NULL,
    name             varchar(100)  NOT NULL,
    name_normalized  varchar(100)  NOT NULL,
    type             varchar(255)  NOT NULL,
    active           boolean       NOT NULL DEFAULT true,
    CONSTRAINT pk_states PRIMARY KEY (id),
    CONSTRAINT uq_states_country_code UNIQUE (country_id, code),
    CONSTRAINT fk_states_country FOREIGN KEY (country_id)
        REFERENCES countries (id) ON DELETE RESTRICT
);

-- ------------------------------------------------------------------- cities
CREATE TABLE cities (
    id               uuid          NOT NULL,
    created_at       timestamp(6)  NOT NULL,
    updated_at       timestamp(6)  NOT NULL,
    state_id         uuid          NOT NULL,
    name             varchar(120)  NOT NULL,
    name_normalized  varchar(120)  NOT NULL,
    active           boolean       NOT NULL DEFAULT true,
    CONSTRAINT pk_cities PRIMARY KEY (id),
    -- Scoped to the state, not global: "Aurangabad" exists in more than one.
    CONSTRAINT uq_cities_state_name UNIQUE (state_id, name_normalized),
    CONSTRAINT fk_cities_state FOREIGN KEY (state_id)
        REFERENCES states (id) ON DELETE RESTRICT
);

-- ------------------------------------------------------------- city_aliases
CREATE TABLE city_aliases (
    id                uuid          NOT NULL,
    created_at        timestamp(6)  NOT NULL,
    updated_at        timestamp(6)  NOT NULL,
    city_id           uuid          NOT NULL,
    alias             varchar(120)  NOT NULL,
    alias_normalized  varchar(120)  NOT NULL,
    source            varchar(255)  NOT NULL,
    CONSTRAINT pk_city_aliases PRIMARY KEY (id),
    -- Deliberately NOT globally unique: one historical name can legitimately
    -- resolve to several cities, and search disambiguates by showing the state.
    CONSTRAINT uq_city_aliases_city_alias UNIQUE (city_id, alias_normalized),
    CONSTRAINT fk_city_aliases_city FOREIGN KEY (city_id)
        REFERENCES cities (id) ON DELETE RESTRICT
);

-- ---------------------------------------------------------------- languages
CREATE TABLE languages (
    id           uuid          NOT NULL,
    created_at   timestamp(6)  NOT NULL,
    updated_at   timestamp(6)  NOT NULL,
    iso_code     varchar(3)    NOT NULL,
    name         varchar(60)   NOT NULL,
    native_name  varchar(60)   NOT NULL,
    active       boolean       NOT NULL DEFAULT true,
    CONSTRAINT pk_languages PRIMARY KEY (id),
    CONSTRAINT uq_languages_iso_code UNIQUE (iso_code),
    CONSTRAINT uq_languages_name UNIQUE (name)
);

-- ------------------------------------------------------------------ indexes
CREATE INDEX idx_states_country       ON states (country_id);
CREATE INDEX idx_cities_state         ON cities (state_id);
CREATE INDEX idx_city_aliases_city    ON city_aliases (city_id);

-- Typeahead. GIN + trigram rather than btree: the query is similarity/ILIKE
-- on a partial term, which a btree cannot serve.
CREATE INDEX idx_cities_name_trgm
    ON cities USING gin (name_normalized gin_trgm_ops);
CREATE INDEX idx_city_aliases_alias_trgm
    ON city_aliases USING gin (alias_normalized gin_trgm_ops);

-- ============================================================================
-- SEED — India
-- Generated from a curated dataset; `name_normalized` computed by the same
-- rule TextNormalizer applies at runtime.
-- ============================================================================





